/**
 * Numeric Qase TestOps case IDs generated by `pnpm qase:sync`, keyed by the
 * catalogue keys from qase/index.ts.
 *
 * Do not edit this file by hand: the sync script rewrites it after creating or
 * matching the cases in TestOps. An empty map simply means no sync has run yet,
 * and every suite still reports by title.
 */
export const qaseCaseIds: Readonly<Record<string, number | undefined>> = {};
